//! 🧪️ Original mounted typed inference and second alias close use finite caller stock and System receipts.
use super::*;
use semio_framework_job::{Generation,OperationId,StepBudget,root_cancel_token};
fn law()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn clock()->Option<u64>{Some(1)}
struct Stock{remaining:RetainedCloneGrant,fuel:u64,born:usize,freed:usize}
impl Stock{
 fn new(law:&serde_json::Value,born:usize,freed:usize)->Self{let row=law["stock"].as_array().unwrap();Self{remaining:RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize},fuel:law["fuel"].as_u64().unwrap(),born,freed}}
 fn grant(&self,demand:RetirementDemand,copy:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:self.remaining.maximum_items.min(1),maximum_copy_bytes:self.remaining.maximum_copy_bytes.min(copy),maximum_capacity_bytes:self.remaining.maximum_capacity_bytes.min(demand.capacity_bytes),maximum_release_bytes:self.remaining.maximum_release_bytes.min(demand.release_bytes),maximum_depth:self.remaining.maximum_depth}}
 fn receive(&mut self,progress:RetainedCloneProgress,work:u64,heap:semio_framework_trace::HeapAllocationObservation){assert!(progress.fits(self.remaining));assert!(work<=self.fuel);assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));self.remaining.maximum_items-=progress.copied_items;self.remaining.maximum_copy_bytes-=progress.copied_bytes;self.remaining.maximum_capacity_bytes-=progress.retained_capacity_bytes;self.remaining.maximum_release_bytes-=progress.released_bytes;self.fuel-=work;self.born+=heap.requested_bytes;self.freed+=heap.released_bytes;}
}
#[test]
fn original_inference_session_same_source_full_paid_close_and_terminal_drop_zero(){
 let law=law();for copy in [1,3,64]{
  let((mut original,pointer),birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let source=law["payload"].as_str().unwrap().to_string();let pointer=source.as_ptr();let mut original=InstanceInferenceSessions::default();original.sessions.push(("same",Box::new(OriginalInferenceSession{body:semio_framework_value::retirement::controlled::ControlledRetirement::new(source).unwrap()})));(original,pointer)});
  let mut sequence=0;let mut stock=Stock::new(&law,birth.requested_bytes,birth.released_bytes);let cancel=root_cancel_token();
  for turn in 0..10000{
   let demand=original.retirement_demands(copy).unwrap();let grant=stock.grant(demand,copy);
   if turn==0{for axis in law["denials"].as_array().unwrap(){let axis=axis.as_str().unwrap();let mut denied=grant;match axis{"items"=>denied.maximum_items=0,"capacity"=>denied.maximum_capacity_bytes=0,"depth"=>denied.maximum_depth=0,"copy"|"release"=>continue,_=>{}}let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(if axis=="work"{0}else{stock.fuel},if axis=="deadline"{0}else{12345},denied),cancel.clone(),clock,&mut sequence,&mut receipt);let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original.close_step(&mut cx,denied));assert_eq!(step.unwrap().progress(),Some(Default::default()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let value=original.sessions[0].1.original_mut().unwrap().downcast_mut::<String>().unwrap();assert_eq!(value.as_ptr(),pointer);assert_eq!(value.as_str(),law["payload"].as_str().unwrap());assert!(!original.closing);}}
   let mut receipt=Default::default();let before=stock.fuel;let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(before,12345,grant),cancel.clone(),clock,&mut sequence,&mut receipt);let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original.close_step(&mut cx,grant));let step=step.unwrap();let progress=step.progress().unwrap();assert!(progress.fits(grant));assert_eq!(cx.retained_progress(),progress);assert_eq!(cx.deadline_us(),12345);stock.receive(progress,before-cx.fuel_remaining(),heap);if original.terminal_is_empty(){break}assert!(turn<9999);
  }
  assert!(original.terminal_is_empty());assert_eq!(stock.born,stock.freed);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(original));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] original inference sameSource typedProducer copy={copy} actualContext finiteStock SystemConservation fullPaidClose terminalDrop0");
 }
}
fn alias_turn(alias:&mut ArtifactInstanceOperationOwnerAliasRetirement,grant:RetainedCloneGrant,fuel:u64,cancel:&semio_framework_job::CancelToken,sequence:&mut u64)->(RetainedCloneProgress,u64,semio_framework_trace::HeapAllocationObservation){
 let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(fuel,12345,grant),cancel.clone(),clock,sequence,&mut receipt);let demand=alias.demands(grant.maximum_copy_bytes).unwrap();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||crate::bounded_ownership::original_lifecycle_step(&mut cx,grant,demand,|cx,loan|{let step=alias.step(cx,loan)?;let terminal=alias.terminal_is_empty();Ok((match step{RetainedCloneStep::Complete(progress)=>PluginLifecycleStep::Complete(progress),RetainedCloneStep::Progress(progress)=>PluginLifecycleStep::Progress(progress)},terminal))}));let progress=step.unwrap().progress().unwrap();assert_eq!(cx.retained_progress(),progress);assert!(progress.fits(grant));(progress,fuel-cx.fuel_remaining(),heap)
}
#[test]
fn original_inference_session_second_arc_alias_same_payload_paid_extract_full_close(){
 let law=law();for copy in [1,3,64]{
  let((handle,peer,pointer),birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let handle=ArtifactInstanceOperationOwnerHandle::new(Box::new(EmptyArtifactInstanceOperationOwner));let pointer=handle.with_inference_session_cold("same",||{let mut source=String::with_capacity(97);source.push_str(law["payload"].as_str().unwrap());source},|source|Ok(source.as_ptr())).unwrap();let peer=handle.clone();(handle,peer,pointer)});let mut stock=Stock::new(&law,birth.requested_bytes,birth.released_bytes);let cancel=root_cancel_token();let mut sequence=0;let(mut alias,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ArtifactInstanceOperationOwnerAliasRetirement::new(handle));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  while !alias.terminal_is_empty(){let demand=alias.demands(copy).unwrap();let grant=stock.grant(demand,copy);for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),Some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant})].into_iter().flatten(){let counts=(std::sync::Arc::strong_count(&peer.inner),std::sync::Arc::strong_count(&peer.inference));let(progress,work,heap)=alias_turn(&mut alias,denied,stock.fuel,&cancel,&mut sequence);assert_eq!(progress,Default::default());assert_eq!(work,0);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((std::sync::Arc::strong_count(&peer.inner),std::sync::Arc::strong_count(&peer.inference)),counts);assert_eq!(peer.with_inference_session_cold("same",String::new,|source|Ok(source.as_ptr())).unwrap(),pointer);}
   let(progress,work,heap)=alias_turn(&mut alias,grant,stock.fuel,&cancel,&mut sequence);assert_eq!(progress.copied_bytes,0);assert_eq!(progress.released_bytes,0);stock.receive(progress,work,heap);assert_eq!(peer.with_inference_session_cold("same",String::new,|source|Ok(source.as_ptr())).unwrap(),pointer);
  }
  assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(alias)).1.released_bytes,0);
  let mut alias=ArtifactInstanceOperationOwnerAliasRetirement::new(peer);let mut extracted=false;
  for turn in 0..10000{let was_arc=alias.inference.is_some();let demand=alias.demands(copy).unwrap();let grant=stock.grant(demand,copy);for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),Some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant})].into_iter().flatten(){let before=(alias.inference.is_some(),alias.inference_owned.is_some());let(progress,work,heap)=alias_turn(&mut alias,denied,stock.fuel,&cancel,&mut sequence);assert_eq!(progress,Default::default());assert_eq!(work,0);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((alias.inference.is_some(),alias.inference_owned.is_some()),before);}
   let(progress,work,heap)=alias_turn(&mut alias,grant,stock.fuel,&cancel,&mut sequence);stock.receive(progress,work,heap);if was_arc&&alias.inference.is_none(){let expected=semio_framework_value::shared_retirement_allocation_bytes::<std::sync::Mutex<InstanceInferenceSessions>>();assert_eq!(progress.released_bytes,expected);let original=alias.inference_owned.as_mut().unwrap().get_mut().unwrap();let source=original.sessions[0].1.original_mut().unwrap().downcast_mut::<String>().unwrap();assert_eq!(source.as_ptr(),pointer);assert_eq!(source.as_str(),law["payload"].as_str().unwrap());assert!(!original.closing);extracted=true;}if alias.terminal_is_empty(){break}assert!(turn<9999);
  }
  assert!(extracted);assert!(alias.terminal_is_empty());assert_eq!(stock.born,stock.freed);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(alias));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] original inference secondArc copy={copy} nonfinalPeerPointer exactFinalArcRelease noPayloadDrop independentDenials finiteStock actualLifecycle fullConservation terminalDrop0");
 }
}
